package com.shopstream.producer;

import java.util.Properties;
import org.apache.kafka.clients.producer.KafkaProducer;
import org.apache.kafka.clients.producer.ProducerConfig;
import org.apache.kafka.clients.producer.ProducerRecord;
import org.apache.kafka.common.serialization.StringSerializer;

public class FirstProducer {

    public static void main(String[] args) {
        Properties props = new Properties();
        props.put(ProducerConfig.BOOTSTRAP_SERVERS_CONFIG, "localhost:9092");
        props.put(ProducerConfig.KEY_SERIALIZER_CLASS_CONFIG, StringSerializer.class.getName());
        props.put(ProducerConfig.VALUE_SERIALIZER_CLASS_CONFIG, StringSerializer.class.getName());

        String orderId = "o-1001";
        String json = """
                {"eventId":"6f1c2d4e-8a47-4d58-9d0e-3b2f6c1a9e10","type":"ORDER_CREATED",\
                "occurredAt":"2026-10-08T10:15:30Z","orderId":"%s","customerId":"c-77",\
                "lines":[{"sku":"SKU-RED-SHOE-42","qty":2,"unitPrice":499.00}],\
                "total":998.00,"currency":"INR"}""".formatted(orderId);

        try (KafkaProducer<String, String> producer = new KafkaProducer<>(props)) {
            ProducerRecord<String, String> record =
                    new ProducerRecord<>("orders", orderId, json);

            producer.send(record, (metadata, exception) -> {
                if (exception != null) {
                    exception.printStackTrace();
                } else {
                    System.out.printf("Sent %s to %s-%d at offset %d%n",
                            orderId, metadata.topic(), metadata.partition(), metadata.offset());
                }
            });
        } // close() blocks until every buffered record has been sent
    }
}

package com.shopstream.producer;

import java.nio.charset.StandardCharsets;
import java.time.Instant;
import java.util.concurrent.ExecutionException;
import java.util.concurrent.TimeUnit;
import java.util.concurrent.TimeoutException;
import org.apache.kafka.clients.producer.Callback;
import org.apache.kafka.clients.producer.Producer;
import org.apache.kafka.clients.producer.ProducerRecord;
import org.apache.kafka.clients.producer.RecordMetadata;
import org.slf4j.Logger;
import org.slf4j.LoggerFactory;

public class OrderEventPublisher {

    private static final Logger log = LoggerFactory.getLogger(OrderEventPublisher.class);
    private static final String TOPIC = "orders";

    private final Producer<String, String> producer;

    public OrderEventPublisher(Producer<String, String> producer) {
        this.producer = producer;
    }

    /** 1. Fire and forget: nobody looks at the result, so failures go unnoticed. */
    public void fireAndForget(String orderId, String json) {
        producer.send(new ProducerRecord<>(TOPIC, orderId, json));
    }

    /** 2. Synchronous: wait for the broker's answer. Safe, but one round trip per record. */
    public RecordMetadata sendAndWait(String orderId, String json)
            throws InterruptedException, ExecutionException, TimeoutException {
        return producer.send(new ProducerRecord<>(TOPIC, orderId, json))
                .get(30, TimeUnit.SECONDS);
    }

    /** 3. Asynchronous with a callback: fast, and every failure is still seen. */
    public void sendAsync(String orderId, String json) {
        producer.send(new ProducerRecord<>(TOPIC, orderId, json), callbackFor(orderId));
    }

    /** 4. Full control: explicit event time and headers. */
    public void sendWithHeaders(String orderId, String json, String traceId, Instant occurredAt) {
        ProducerRecord<String, String> record =
                new ProducerRecord<>(TOPIC, null, occurredAt.toEpochMilli(), orderId, json);
        record.headers().add("traceId", traceId.getBytes(StandardCharsets.UTF_8));
        record.headers().add("eventType", "ORDER_CREATED".getBytes(StandardCharsets.UTF_8));
        producer.send(record, callbackFor(orderId));
    }

    private Callback callbackFor(String orderId) {
        return (metadata, exception) -> {
            if (exception != null) {
                log.error("Order {} was not published", orderId, exception);
                // keep it short: hand over to a retry queue, an outbox table or an alert
            } else {
                log.debug("Order {} stored at {}-{} offset {}",
                        orderId, metadata.topic(), metadata.partition(), metadata.offset());
            }
        };
    }
}

AtomicInteger failures = new AtomicInteger();
for (OrderCreated event : events) {
    ProducerRecord<String, String> record =
            new ProducerRecord<>("orders", event.orderId(), toJson(event));
    producer.send(record, (metadata, exception) -> {
        if (exception != null) {
            failures.incrementAndGet();
        }
    });
}
producer.flush();   // every callback above has run when this returns
if (failures.get() > 0) {
    throw new IllegalStateException(failures.get() + " events were not published");
}

package com.shopstream.producer;

import java.util.Properties;
import org.apache.kafka.clients.producer.ProducerConfig;
import org.apache.kafka.common.errors.AuthorizationException;
import org.apache.kafka.common.errors.RecordTooLargeException;
import org.apache.kafka.common.errors.SerializationException;
import org.apache.kafka.common.errors.TimeoutException;
import org.apache.kafka.common.serialization.StringSerializer;

public final class ReliableProducerSupport {
    public enum Action { PARK, STOP, RESEND_LATER, ALERT }

    private ReliableProducerSupport() { }

    public static Properties props(String bootstrapServers) {
        Properties props = new Properties();
        props.put(ProducerConfig.BOOTSTRAP_SERVERS_CONFIG, bootstrapServers);
        props.put(ProducerConfig.KEY_SERIALIZER_CLASS_CONFIG, StringSerializer.class.getName());
        props.put(ProducerConfig.VALUE_SERIALIZER_CLASS_CONFIG, StringSerializer.class.getName());
        props.put(ProducerConfig.CLIENT_ID_CONFIG, "order-service");
        props.put(ProducerConfig.ACKS_CONFIG, "all");
        props.put(ProducerConfig.ENABLE_IDEMPOTENCE_CONFIG, true);
        props.put(ProducerConfig.MAX_IN_FLIGHT_REQUESTS_PER_CONNECTION, 5);
        props.put(ProducerConfig.REQUEST_TIMEOUT_MS_CONFIG, 30_000);
        props.put(ProducerConfig.DELIVERY_TIMEOUT_MS_CONFIG, 120_000);
        return props;
    }

    /** Decide what to do with a failed send, based on the kind of exception. */
    public static Action decide(Exception e) {
        return switch (e) {
            case RecordTooLargeException ex -> Action.PARK;     // retrying gives the same error
            case SerializationException ex -> Action.PARK;      // a bug: fix the code
            case AuthorizationException ex -> Action.STOP;      // fix the ACLs first
            case TimeoutException ex -> Action.RESEND_LATER;    // outcome unknown
            default -> Action.ALERT;
        };
    }
}

package com.shopstream.producer;

import java.nio.charset.StandardCharsets;
import java.util.Arrays;
import java.util.Map;
import java.util.concurrent.ThreadLocalRandom;
import org.apache.kafka.clients.producer.Partitioner;
import org.apache.kafka.common.Cluster;

/** Keys that start with "urgent:" go to partition 0; everything else to partitions 1..n-1. */
public class ExpressLanePartitioner implements Partitioner {

    private static final byte[] URGENT = "urgent:".getBytes(StandardCharsets.UTF_8);

    @Override
    public void configure(Map<String, ?> configs) {
        // nothing to configure in this example
    }

    @Override
    public int partition(String topic, Object key, byte[] keyBytes,
                         Object value, byte[] valueBytes, Cluster cluster) {
        int partitions = cluster.partitionsForTopic(topic).size();
        if (partitions == 1) {
            return 0;
        }
        if (keyBytes == null) {
            return ThreadLocalRandom.current().nextInt(1, partitions);
        }
        if (keyBytes.length >= URGENT.length
                && Arrays.equals(keyBytes, 0, URGENT.length, URGENT, 0, URGENT.length)) {
            return 0;
        }
        return 1 + Math.floorMod(Arrays.hashCode(keyBytes), partitions - 1);
    }

    @Override
    public void close() {
        // nothing to release
    }
}
